import { supabase } from '../supabaseClient.js';
import { getCurrentUser } from '../auth.js';

export function openYouTubeVideo(youtubeId) {
    if (!youtubeId) {
        console.error('YouTube ID is missing.');
        return;
    }
    const youtubeUrl = `https://www.youtube.com/watch?v=${youtubeId}`;
    window.open(youtubeUrl, '_blank');
}

export async function trackWatchedVideo(videoId) { // Made async
    if (!videoId) return;

    const user = await getCurrentUser(); // Use await

    if (user) {
        try {
            // Fetch existing data first
            let { data: profile, error: fetchError } = await supabase
                .from('user_profiles')
                .select('watched_history, watched_dates')
                .eq('id', user.id)
                .single();

            // PGRST116 means no row was found, which is not an error in this context for a new user.
            if (fetchError && fetchError.code !== 'PGRST116') {
                console.error('Error fetching user profile for watched history:', fetchError);
                // Fallback or alternative handling could be added here.
                // For now, we'll log the error and not proceed with Supabase update if profile fetch fails.
                // Optionally, one could try to use localStorage here as a fallback.
                // However, to keep logic distinct, if a user is logged in, we prioritize Supabase.
                return;
            }

            let watchedHistory = (profile && profile.watched_history) ? profile.watched_history : [];
            let watchedDates = (profile && profile.watched_dates) ? profile.watched_dates : {};

            // Update history and dates
            if (!watchedHistory.includes(videoId)) {
                watchedHistory.push(videoId);
            }
            watchedDates[videoId] = new Date().toISOString();

            // Upsert the updated data
            const { error: upsertError } = await supabase
                .from('user_profiles')
                .upsert({
                    id: user.id,
                    watched_history: watchedHistory,
                    watched_dates: watchedDates,
                    updated_at: new Date().toISOString()
                }); // .eq('id', user.id) is not strictly needed for upsert with primary key, but doesn't hurt.

            if (upsertError) {
                console.error('Error updating watched history in Supabase:', upsertError);
            } else {
                console.log(`Tracked video ${videoId} as watched in Supabase for user ${user.id}.`);
            }

        } catch (error) {
            console.error('Exception tracking watched video in Supabase:', error);
            // Consider if localStorage fallback is desired here on general exception.
        }
    } else {
        // Existing localStorage logic for non-logged-in users
        try {
            let watchedHistory = JSON.parse(localStorage.getItem('watchedHistory') || '[]');
            if (!watchedHistory.includes(videoId)) {
                watchedHistory.push(videoId);
                localStorage.setItem('watchedHistory', JSON.stringify(watchedHistory));
            }

            let watchedDates = JSON.parse(localStorage.getItem('watchedDates') || '{}');
            watchedDates[videoId] = new Date().toISOString();
            localStorage.setItem('watchedDates', JSON.stringify(watchedDates));

            console.log(`Tracked video ${videoId} as watched in localStorage.`);
        } catch (error) {
            console.error('Error tracking watched video in localStorage:', error);
        }
    }
}
